const items = $input.all();
const j = (items[0] && items[0].json) || {};
const meta = j.meta || {};
const errors = meta.errors || {};
const keys = Object.keys(errors);
if (keys.length > 0) {
  throw new Error('automation feed meta.errors: ' + JSON.stringify(errors));
}
return $input.all();

const items = $input.all();
const j = (items[0] && items[0].json) || {};
let day = null;
if (Array.isArray(j.data) && j.data.length) {
  const first = j.data[0];
  if (first && Array.isArray(first.rows)) {
    day = first;
  } else if (first && typeof first === 'object' && typeof first.name === 'string') {
    day = { date: (j.meta && j.meta.date) || '', rows: j.data, total: (j.meta && j.meta.total) || null };
  }
} else if (Array.isArray(j.rows)) {
  day = j;
}
const rows = (day && Array.isArray(day.rows)) ? day.rows : [];
const aktif = rows.filter((r) => r && r.status !== 'Cancelled');
const t = (day && day.total) || {};
const dayNames = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
const months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
function rupiah(n) {
  n = Number(n) || 0;
  return 'Rp. ' + n.toLocaleString('id-ID');
}
function tglPendek(iso) {
  const p = String(iso || '').split('-');
  if (p.length !== 3 || !p[0]) return String(iso || '');
  const dt = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
  if (isNaN(dt.getTime())) return String(iso || '');
  return dayNames[dt.getDay()] + ', ' + Number(p[2]) + ' ' + months[Number(p[1]) - 1] + ' ' + p[0];
}
function jmlMeja(r) {
  const s = (r.tables !== undefined && r.tables !== null) ? r.tables : r.table;
  return String(s === undefined || s === null ? '' : s).split(',').map((x) => x.trim()).filter((x) => x !== '').length;
}
const totalPax = (t.pax !== undefined && t.pax !== null) ? t.pax : aktif.reduce((a, r) => a + (Number(r.pax) || 0), 0);
const totalRes = (t.reservasi !== undefined && t.reservasi !== null) ? t.reservasi : aktif.length;
const totalMeja = aktif.reduce((a, r) => a + jmlMeja(r), 0);
const lines = [];
lines.push('Halo, Selamat Sore Team! Bagaimana kabarnya hari ini?');
lines.push('Berikut Informasi Reservasi pada hari ini ya :');
lines.push('');
lines.push('KOORDINASI KEDATANGAN');
lines.push('Laksamana Muda | ' + tglPendek(day && day.date));
lines.push('Total: ' + totalPax + ' pax | ' + totalRes + ' reservasi | ' + totalMeja + ' meja');
lines.push('-----------------');
if (!aktif.length) {
  lines.push('Belum ada reservasi.');
} else {
  aktif.forEach((r, i) => {
    const nama = String(r.name || '-').toUpperCase();
    const jam = String(r.time || '--:--').slice(0, 5);
    const meja = String((r.tables !== undefined && r.tables !== null) ? r.tables : (r.table || '-')).trim() || '-';
    const pax = (r.pax === undefined || r.pax === null) ? '-' : r.pax;
    const dp = Number(r.dpAmount) || 0;
    const dpTxt = dp > 0 ? rupiah(dp) : 'Belum DP';
    lines.push((i + 1) + '. ' + nama + ' | ' + jam + ' | ' + meja + ' | ' + pax + ' | ' + dpTxt);
  });
}
return [{ json: { text: lines.join('\n') } }];
